head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS21301.xml";
scwin.nPreRow = -1;
scwin.vISUR_CD21301 = "";
scwin.vISUR_NM21301 = "";
scwin.add_gb21301 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************
 *  화면 초기화
 *********************************************/
scwin.fn_Init = function() {
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_KEY, false);
    $c.stf.showObj(txb_PREPAY_NO, false);
    $c.cm.PanelToGroupBox(panel_2);

    //fn_com_isur(txb_ISUR_CD, txb_COM_NM);

    var vTemp = frame.FrameID;
    var Temp2 = vTemp.split("|")[1];
    var vISUR_CD = Temp2.split("=")[1]; // ISUR_CD


    if (vISUR_CD != "") {
        //기존 발행기관

        //발행기관 비활성화
        txb_ISUR_CD.setReadOnly(true);
        txb_COM_NM.setReadOnly(true);
        txb_ISUR_CD.setValue(vISUR_CD);
        txb_COM_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_COM_NM2));

        //전역변수 세팅	
        scwin.vISUR_CD21301 = txb_ISUR_CD.getValue();
        scwin.vISUR_NM21301 = txb_COM_NM.getValue();
        scwin.add_gb21301 = "SEARCH";

        //단순조회
        scwin.fn_listPrepayChg("NODATA", "NODATA");
    }
};




/********************************************
 *  데이터셋 초기화.
 *********************************************/
scwin.fn_InitDs = function() {
    dts_PayInfo.removeAll();
};
scwin.arrPar = new Array();
/********************************************** 
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************
 * 선납잔액 조회
 *********************************************/
scwin.fn_listPrepayChg = function(ISUR_CD, COM_NM) {
    // 데이터셋 초기화
    //fn_InitDs();

    // 입력 후 재조회를 위해 세팅
    //if (add_gb21301 == "SEARCH") {
    if (ISUR_CD == "NODATA") {
        ISUR_CD = scwin.vISUR_CD21301;
        txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
        txb_COM_NM.setValue(scwin.vISUR_NM21301);
    } else {
        //전역변수 세팅	
        scwin.vISUR_CD21301 = ISUR_CD;
        //alert("전역변수vISUR_CD21301 :"+vISUR_CD21301);
        scwin.vISUR_NM21301 = COM_NM;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_PayInfo);

    //선납잔액 조회
    var url = "/PrepayInfoAction.do?method=readPrepayChg";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ISUR_CD == "NODATA") {
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    } else {
        url += "&ISUR_CD=" + ISUR_CD;
    }
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************
 * 선납금 조회
 *********************************************/
scwin.fn_listPrepayChg3 = function() {
    //선납금등록내역 Grid 조회
    var url = "/PrepayInfoAction.do?method=listPrepayChg";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_PayInfo.DataID = encodeURI(url);
    dts_PayInfo.Reset();
};


/********************************************
 * 선납금 전환대상 조회 (신청내역 - 건납만)
 *********************************************/
scwin.fn_listPrepayChg_Appl = function() {
    //alert(getObjectValue(txb_ISUR_CD));

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDREQINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listTbldBscdaplInquiry" + "&{P}ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + // 발행기관코드
        "&{P}STD_CD_GRNT_FEE_PROCS_STAT_CD=2" + // 납부구분 건납
        "&{P}STD_CD_APPL_CONTN_TP_CD="; // 채권 03425	표준코드신청내용구분코드
    dts_ApplInfo.DataID = encodeURI(url);
    dts_ApplInfo.reset();
    $c.cm.ShowWin(grd_ApplInfo); // 그리드명을 표기

};


/********************************************
 * 선납금 전환 처리
 *********************************************/
scwin.ins_PrepayChg = function() {
    // 선납금전환 대상을 점검
    if (scwin.fn_chkValid() == false) return;
    var msg = $c.stf.getMessageParam("MSG-A006", "선납금 전환");
    var res = window.confirm(msg);
    if (res) {
        // 선택된 Row만 서버로 전송..
        scwin.fn_SetTransData();
        trs_Return.Action = "/PrepayInfoAction.do?method=registerPrepayChg" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Return.KeyName = "toinb_dataid4";
        trs_Return.KeyValue = "JSP(I:pInput=dts_ApplInfo)";
        trs_Return.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
        trs_Return.Post();
    }
};



/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 선납금전환 대상을 점검
 ***********************************************/
scwin.fn_chkValid = function() {
    var cnt = 0;
    var cnt2 = 0;
    var cnt3 = 0;
    var visurCd = "";
    var vDepDd = "";
    for (var nRow = 1; nRow <= dts_ApplInfo.getTotalRow(); nRow++) {
        if (dts_ApplInfo.getCellData(nRow, "CHK") == "T") {
            cnt++;
            if ("2" != (dts_ApplInfo.getCellData(nRow, "STD_CD_GRNT_FEE_PROCS_STAT_CD"))) {
                cnt2++;
            }
            if ("0" != (dts_ApplInfo.getCellData(nRow, "DEPO_AMT_FMT"))) {
                cnt3++;
            }
        }
    }
    //alert("cnt: " +cnt);
    if (eval(cnt) == 0) {
        $c.win.alert("선납금전환 대상을 체크하세요.");
        return false;
    }
    if (eval(cnt2) > 0) {
        $c.win.alert("선납금전환은 납입구분이 [건납]인 경우에만 가능합니다.");
        return false;
    }
    if (eval(cnt3) > 0) {
        $c.win.alert("이미 입금된 건은 선납으로 전환 할 수 없습니다.");
        return false;
    }
    return true;
};


/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_ApplInfo.getRowPosition();
    dts_ApplInfo.setCellData(nRow, "CHK", "T");
};


/********************************************** 
 * 함수명   : fn_setCheckBox
 * 설명       : 그리드 체크박스 전체선택 또는 전체선택 해제
 ***********************************************/
scwin.fn_setCheckBox = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        dtsObj.setCellData(i, "CHK", vcd);
    }
    grdObj.setBroadcast(true);
};


/********************************************** 
 * 함수명   : fn_chkValid
 * 설명       : 선납전환 체크대상을 점검
 ***********************************************/
scwin.fn_chkClickValid = function(col, colid, bCheck) {
    //alert("col : " + col);
    //alert(" colid: " + colid);
    //alert(" bCheck: " + bCheck);

    if (bCheck == '1') {
        //체크선택
        if ("2" != (dts_ApplInfo.getCellData(col, "STD_CD_GRNT_FEE_PROCS_STAT_CD")) || "0" != (dts_ApplInfo.getCellData(col, "DEPO_AMT_FMT"))) {
            $c.win.alert("이미 입금된 건은 선납으로 전환 할 수 없습니다.");
            dts_ApplInfo.setCellData(col, "CHK", "0");
            return false;
        }
    }
};
scwin.grd_ApplInfo_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.dts_detail_OnLoadCompleted = function() {
    scwin.fn_listPrepayChg3(); //기존선급금 존재기관

};
scwin.dts_PayInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_PayInfo);
    $c.stf.alert_error(dts_PayInfo);
};
scwin.dts_PayInfo_OnLoadCompleted = function(rowcount) {
    if (dts_PayInfo.errorMsg) {
        $c.win.alert(dts_PayInfo.errorMsg);
    } else {
        if (txb_PREPAY_BAL.getValue() == "") {
            txb_TotalCnt.setValue("총 0건"); //신규

        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건"); //기존선급금 존재기관

        }
    }
    $c.cm.CloseWin(rowcount, grd_PayInfo);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    }
    scwin.fn_listPrepayChg_Appl();
};
scwin.dts_ApplInfo_OnLoadCompleted = function(rowcount) {
    if (dts_ApplInfo.errorMsg) {
        $c.win.alert(dts_ApplInfo.errorMsg);
        btn_PrepayChg.setDisabled(true);
        btn_PrepayChg.src = "../img/ins/btn_prepay_chg_d.png";
    } else {
        txb_TotalCnt_Appl.setValue("총 " + rowcount + "건"); //선급금 전환대상
        btn_PrepayChg.setDisabled(false);
        btn_PrepayChg.src = "../img/ins/btn_prepay_chg.png";
    }
    $c.cm.CloseWin(rowcount, grd_ApplInfo);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
        btn_PrepayChg.setDisabled(true);
        btn_PrepayChg.src = "../img/ins/btn_prepay_chg_d.png";
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.btn_PrepayChg_onclick = function() {
    scwin.ins_PrepayChg();
};
scwin.grd_ApplInfo_OnHeadCheckClick = function(col, colid, bCheck) {
    scwin.fn_setCheckBox(grd_ApplInfo, dts_ApplInfo, bCheck);
};
scwin.grd_ApplInfo_OnCheckClick = function(col, colid, bCheck) {
    scwin.fn_chkClickValid(col, colid, bCheck);
};
scwin.trs_Return_OnFail = function() {
    alert_tr_error(trs_Return);
};
scwin.trs_Return_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.fn_listPrepayChg_Appl();
};
